    { word: "plastic", phonetic: "/ˈplæstɪk/", def: "A synthetic material made from a wide range of organic polymers that can be molded into shape.", defVn: "nhựa, chất dẻo", pos: "noun", ex: ["Reduce single-use plastic straws and bags to protect our oceans.", "Recycle plastic bottles in the blue bin."], exVn: ["Hãy giảm thiểu ống hút và túi nhựa dùng một lần để bảo vệ đại dương.", "Tái chế chai nhựa vào thùng rác màu xanh nhé."] },
    { word: "glass", phonetic: "/ɡlæs/", def: "A hard, brittle substance, typically transparent or translucent, made by fusing sand.", defVn: "thủy tinh, kính trong suốt", pos: "noun", ex: ["Handle the delicate crystal glass vase with gentle care.", "Modern skyscrapers use energy-efficient insulated glass."], exVn: ["Hãy cầm chiếc lọ hoa thủy tinh pha lê dễ vỡ thật nhẹ nhàng.", "Các tòa cao ốc hiện đại sử dụng kính cách nhiệt tiết kiệm năng lượng."] },
    { word: "paper", phonetic: "/ˈpeɪpər/", def: "Material manufactured in thin sheets from the pulp of wood or other fibrous substances.", defVn: "giấy viết, giấy in", pos: "noun", ex: ["Traditional Vietnamese Do paper is handmade from mulberry bark.", "Write your notes on recycled notebook paper."], exVn: ["Giấy Dó truyền thống của Việt Nam được làm thủ công từ vỏ cây dướng.", "Hãy viết ghi chép lên giấy sổ tay tái chế nhé."] },
    { word: "cotton", phonetic: "/ˈkɑːtn/", def: "A soft white fibrous substance that surrounds the seeds of a tropical plant and is made into textile fiber.", defVn: "bông vải cotton (thấm hút, thoáng mát)", pos: "noun", ex: ["100% natural organic cotton t-shirts are breathable and soft.", "Cotton sheets keep you comfortable during summer sleep."], exVn: ["Áo phông 100% cotton hữu cơ tự nhiên rất thoáng khí và mềm mại.", "Ga giường cotton giúp bạn thoải mái suốt giấc ngủ mùa hè."] },
    { word: "silk", phonetic: "/sɪlk/", def: "A fine, strong, soft, lustrous fiber produced by silkworms in making cocoons and collected to make thread.", defVn: "lụa tơ tằm óng ả", pos: "noun", ex: ["Van Phuc Silk Village in Hanoi weaves world-famous luxurious silk.", "A smooth silk scarf glides gracefully over shoulders."], exVn: ["Làng lụa Vạn Phúc ở Hà Nội dệt nên những dải lụa tơ tằm sang trọng nức tiếng.", "Chiếc khăn lụa mềm mại khoác duyên dáng trên bờ vai."] },
    { word: "wool", phonetic: "/wʊl/", def: "The fine, soft curly or wavy hair forming the coat of a sheep, goat, or similar animal.", defVn: "len cừu ấm áp", pos: "noun", ex: ["Knitted Merino wool sweaters provide exceptional natural warmth in winter.", "She wore a cozy woolen beanie."], exVn: ["Những chiếc áo len dệt từ lông cừu Merino mang lại hơi ấm tự nhiên vượt trội.", "Cô ấy đội một chiếc mũ len ấm cúng."] },
    { word: "leather", phonetic: "/ˈleðər/", def: "A material made from the skin of an animal by tanning or a similar process.", defVn: "chất liệu da thuộc", pos: "noun", ex: ["Genuine leather shoes and wallets age beautifully over years of use.", "He wore a classic brown leather jacket."], exVn: ["Giày và ví bằng da thật càng dùng lâu năm lại càng bóng đẹp.", "Anh ấy mặc chiếc áo khoác da màu nâu cổ điển."] },
    { word: "rubber", phonetic: "/ˈrʌbər/", def: "A tough elastic polymeric substance made from the latex of a tropical plant.", defVn: "cao su đàn hồi", pos: "noun", ex: ["Natural rubber tires provide strong grip and road safety.", "Rubber boots protect your feet when working in mud."], exVn: ["Lốp xe làm từ cao su thiên nhiên mang lại độ bám đường tốt và an toàn.", "Ủng cao su bảo vệ chân khi làm việc trong bùn lầy."] },
    { word: "stone", phonetic: "/stoʊn/", def: "Hard solid non-metallic mineral matter of which rock is made.", defVn: "đá tự nhiên, tảng đá", pos: "noun", ex: ["The ancient temple was constructed from solid carved limestone blocks.", "Smooth river stones decorate the zen garden."], exVn: ["Ngôi đền cổ được xây dựng từ những khối đá vôi đẽo gọt chắc chắn.", "Những viên sỏi sông nhẵn bóng trang trí khu vườn thiền."] },
    { word: "clay", phonetic: "/kleɪ/", def: "A stiff, sticky fine-grained earth that can be molded when wet, and is dried and baked to make bricks and pottery.", defVn: "đất sét nặn gốm", pos: "noun", ex: ["Bat Trang artisans shape wet natural clay on a pottery wheel.", "Terra-cotta clay pots allow plant roots to breathe."], exVn: ["Các nghệ nhân Bát Tràng tạo hình đất sét ướt trên bàn xoay gốm.", "Chậu đất nung giúp rễ cây có thể thở và thoát nước tốt."] },
    { word: "gold", phonetic: "/ɡoʊld/", def: "A yellow precious metal, the chemical element of atomic number 79, used in jewelry and decoration.", defVn: "vàng ròng nguyên chất", pos: "noun", ex: ["Pure 24-karat gold has an unmistakable deep warm luster.", "Traditional jewelry craftsmen carve intricate gold ornaments."], exVn: ["Vàng ròng 24K có ánh kim ấm áp đậm đà không thể nhầm lẫn.", "Những người thợ kim hoàn truyền thống chạm khắc đồ trang sức bằng vàng tinh xảo."] },
    { word: "silver", phonetic: "/ˈsɪlvər/", def: "A precious shiny grayish-white metal, the chemical element of atomic number 47.", defVn: "bạc, ánh bạc kim loại", pos: "noun", ex: ["Sterling silver tableware gleamed brightly under candlelight.", "Silver has natural antimicrobial properties."], exVn: ["Bộ đồ ăn bằng bạc 925 sáng lấp lánh dưới ánh nến lung linh.", "Bạc có đặc tính kháng khuẩn tự nhiên tuyệt vời."] },
    { word: "iron", phonetic: "/ˈaɪərn/", def: "A strong, hard magnetic silvery-gray metal, the chemical element of atomic number 26.", defVn: "sắt, gang thép", pos: "noun", ex: ["Cast iron cookware retains heat evenly for delicious searing.", "Wrought iron balcony railings add vintage European charm."], exVn: ["Dụng cụ nấu ăn bằng gang giữ nhiệt đều giúp món áp chảo thơm ngon.", "Lan can ban công bằng sắt uốn nghệ thuật mang nét quyến rũ châu Âu cổ kính."] }
